        oracle.registerTrustedNode(address(this));
        oracle.updatePrice(1e6);

        uint256 collateral = 1.2e6;
        uint256 debt = 1e18;



        (uint256 _currentPrice, , , uint8 _decimals) = IPriceOracle(
            oracle
